theory:
### DateTime vs DateTimeOffset

`DateTime` mixes **unspecified**, UTC, and local kinds; bugs appear when you subtract values with different kinds or assume `Now` is universal. Prefer **`DateTimeOffset`** for instants that must round-trip with an explicit offset, and be deliberate about **UTC** at storage boundaries.

### TimeSpan and arithmetic

`TimeSpan` measures elapsed time between ticks; it does not encode calendar concepts. Calendars use `DateOnly` / `TimeOnly` (.NET 6+) for human schedules without tying them to a time zone ambiguously.

Time zone conversions should go through **`TimeZoneInfo`** rather than fixed offsets for historical DST rules. For monotonic measurements (timeouts, profiling), `Stopwatch` uses a high-resolution clock unrelated to wall time.

```csharp
using System;

var utc = DateTime.UtcNow;

var dto = DateTimeOffset.UtcNow;

var span = TimeSpan.FromMinutes(90);

Console.WriteLine($"{utc:o} | {dto:o} | {span}");
```

exercises.starter_code:
using System;
using System.Globalization;

// new DateTimeOffset(...)

exercises.solution:
using System;
using System.Globalization;

var t = new DateTimeOffset(2024, 1, 1, 12, 0, 0, TimeSpan.Zero);
Console.WriteLine($"{t.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture)} UTC");

using System;
using System.Globalization;

var tz = TimeZoneInfo.FindSystemTimeZoneById("Asia/Tokyo");
var wall = new DateTime(2023, 3, 15, 14, 30, 0, DateTimeKind.Unspecified);
var offset = tz.GetUtcOffset(wall);
var local = new DateTimeOffset(wall, offset);
Console.WriteLine($"Year: {local.Year}");
Console.WriteLine($"Month: {local.ToString("MMMM", CultureInfo.InvariantCulture)}");
Console.WriteLine($"Day: {local.Day}");
Console.WriteLine($"Hour: {local.Hour}");
Console.WriteLine($"Minute: {local.Minute}");
Console.WriteLine($"Weekday: {local.ToString("dddd", CultureInfo.InvariantCulture)}");

using System;

var d = TimeSpan.FromHours(2) + TimeSpan.FromMinutes(30);
Console.WriteLine($"{(int)d.TotalHours}h{d.Minutes}m{d.Seconds}s");
Console.WriteLine("500ms");

exercises.starter_code:
using System;
using System.Globalization;

// DateTimeOffset.ParseExact(..., DateTimeStyles.AssumeUniversal | AdjustToUniversal)

exercises.solution:
using System;
using System.Globalization;

var s = "2024-06-15 09:30:00";
var dto = DateTimeOffset.ParseExact(
    s,
    "yyyy-MM-dd HH:mm:ss",
    CultureInfo.InvariantCulture,
    DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal);
Console.WriteLine($"{dto.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture)} UTC");

using System;
using System.Globalization;

var t = new DateTimeOffset(2024, 7, 4, 16, 0, 0, TimeSpan.Zero);
Console.WriteLine(t.ToString("MM/dd/yyyy", CultureInfo.InvariantCulture));
var longForm = t.ToString("dddd, MMMM d, yyyy", CultureInfo.InvariantCulture);
Console.WriteLine(longForm.Replace("  ", " "));

exercises.starter_code:
using System;
using System.Globalization;

// dto.AddDays / AddHours

exercises.solution:
using System;
using System.Globalization;

var t = new DateTimeOffset(2024, 1, 15, 10, 0, 0, TimeSpan.Zero);
var outT = t + TimeSpan.FromDays(3) + TimeSpan.FromHours(5);
Console.WriteLine($"{outT.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture)} UTC");

using System;

var now = new DateTimeOffset(2024, 12, 25, 0, 0, 0, TimeSpan.Zero);
var then = new DateTimeOffset(2024, 11, 25, 0, 0, 0, TimeSpan.Zero);
var diff = now - then;
Console.WriteLine($"{(int)diff.TotalHours}h0m0s");
Console.WriteLine($"Days: {(int)diff.TotalDays}");

using System;

var t1 = new DateTimeOffset(2024, 1, 1, 0, 0, 0, TimeSpan.Zero);
var t2 = new DateTimeOffset(2024, 12, 31, 0, 0, 0, TimeSpan.Zero);
Console.WriteLine($"January 1 is before December 31: {(t1 < t2).ToString().ToLowerInvariant()}");
Console.WriteLine($"December 31 is after January 1: {(t2 > t1).ToString().ToLowerInvariant()}");

using System;
using System.Globalization;

var t = new DateTimeOffset(2024, 6, 1, 10, 15, 30, TimeSpan.Zero);
Console.WriteLine($"{t.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture)} UTC");
Console.WriteLine($"Hour: {t.Hour}");
Console.WriteLine($"Minute: {t.Minute}");
var after = t.AddSeconds(1);
Console.WriteLine($"After +1s: {after.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture)} UTC");
